"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[20095],{42014:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>o,contentTitle:()=>i,default:()=>c,frontMatter:()=>s,metadata:()=>r,toc:()=>d});var h=n(31085),a=n(71184);const s={sidebar_position:11,slug:"/bible/1_Machabees/1_Machabees_11",title:"1 Machabees 11",hide_table_of_contents:!0},i="1 Machabees",r={id:"bible/1 Machabees/1 Machabees 11",title:"1 Machabees 11",description:"Chapter 11",source:"@site/docs/bible/1 Machabees/1 Machabees 11.md",sourceDirName:"bible/1 Machabees",slug:"/bible/1_Machabees/1_Machabees_11",permalink:"/bibleNotes/docs/bible/1_Machabees/1_Machabees_11",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/1 Machabees/1 Machabees 11.md",tags:[],version:"current",sidebarPosition:11,frontMatter:{sidebar_position:11,slug:"/bible/1_Machabees/1_Machabees_11",title:"1 Machabees 11",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"1 Machabees 10",permalink:"/bibleNotes/docs/bible/1_Machabees/1_Machabees_10"},next:{title:"1 Machabees 12",permalink:"/bibleNotes/docs/bible/1_Machabees/1_Machabees_12"}},o={},d=[{value:"Chapter 11",id:"chapter-11",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,a.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(t.h1,{id:"1-machabees",children:"1 Machabees"}),"\n",(0,h.jsx)(t.h2,{id:"chapter-11",children:"Chapter 11"}),"\n",(0,h.jsx)(t.p,{children:"Ptolemee invades the kingdom of Alexander:  the latter is slain:  and the former dies soon after.  Demetrius honours Jonathan, and is rescued by the Jews from his own subjects in Antioch.  Antiochus the younger favours Jonathan.  His exploits in divers places."}),"\n",(0,h.jsx)(n,{verse:1,children:"And the king of Egypt gathered together an army, like the sand that lieth upon the sea shore, and many ships: and he sought to get the kingdom of Alexander by deceit, and join it to his own kingdom."}),"\n",(0,h.jsx)(n,{verse:2,children:"And he went out into Syria with peaceable words and they opened to him the cities, and met him: for king Alexander had ordered them to go forth to meet him, because he was his father in law."}),"\n",(0,h.jsx)(n,{verse:3,children:"Now when Ptolemee entered into the cities, he put garrisons of soldiers in every city."}),"\n",(0,h.jsx)(n,{verse:4,children:"And when he came near to Azotns, they shewed him the temple of Dagon that was burnt with fire, and Azotus, and the suburbs thereof, that were destroyed, and the bodies that were cast abroad, and the graves of them that were slain in the battle, which they had made near the way."}),"\n",(0,h.jsx)(n,{verse:5,children:"And they told the king that Jonathan had done these things, to make him odious: but the king held his peace."}),"\n",(0,h.jsx)(n,{verse:6,children:"And Jonathan came to meet the king at Joppe with glory, and they saluted one another, and they lodged there."}),"\n",(0,h.jsx)(n,{verse:7,children:"And Jonathan went with the king as far as the river, called Eleutherus: and he returned into Jerusalem."}),"\n",(0,h.jsx)(n,{verse:8,children:"And king Ptolemee got the dominion of the cities by the sea side, even to Seleucia, and he devised evil designs against Alexander."}),"\n",(0,h.jsx)(n,{verse:9,children:"And he sent ambassadors to Demetrius, saying: Come, let us make a league between us, and I will give thee my daughter whom Alexander hath, and thou shalt reign in the kingdom of thy father."}),"\n",(0,h.jsx)(n,{verse:10,children:"For I repent that I have given him my daughter: for he hath sought to kill me."}),"\n",(0,h.jsx)(n,{verse:11,children:"And he slandered him, because he coveted his kingdom,"}),"\n",(0,h.jsx)(n,{verse:12,children:"And he took away his daughter, and gave her to Demetrius, and alienated himself from Alexander, and his enmities were made manifest."}),"\n",(0,h.jsx)(n,{verse:13,children:"And Ptolemee entered into Antioch, and set two crowns upon his head, that of Egypt, and that of Asia."}),"\n",(0,h.jsx)(n,{verse:14,children:"Now king Alexander was in Cilicia at that time: because they that were in those places had rebelled."}),"\n",(0,h.jsx)(n,{verse:15,children:"And when Alexander heard of it, he came to give him battle: and king Ptolemee brought forth his army, and met him with a strong power, and put him to flight."}),"\n",(0,h.jsx)(n,{verse:16,children:"And Alexander fled into Arabia, there to be protected: and king Ptolemee was exalted."}),"\n",(0,h.jsx)(n,{verse:17,children:"And Zabdiel the Arabian took off Alexander's head, and sent it to Ptolemee."}),"\n",(0,h.jsx)(n,{verse:18,children:"And king Ptolemee died the third day after: and they that were in the strong holds were destroyed by them that were within the camp."}),"\n",(0,h.jsx)(n,{verse:19,children:"And Demetrius reigned in the hundred and sixty-seventh year."}),"\n",(0,h.jsx)(n,{verse:20,children:"In those days Jonathan gathered together them that were in Judea, to take the castle that was in Jerusalem: and they made many engines of war against it."}),"\n",(0,h.jsx)(n,{verse:21,children:"Then some wicked men that hated their own nation, went away to king Demetrius, and told him that Jonathan was besieging the castle."}),"\n",(0,h.jsx)(n,{verse:22,children:"And when he heard it, he was angry: and forthwith he came to Ptolemais, and wrote to Jonathan that he should not besiege the castle, but should come to him in haste, and speak to him."}),"\n",(0,h.jsx)(n,{verse:23,children:"But when Jonathan heard this, he bade them besiege it still: and he chose some of the ancients of Israel, and of the priests, and put himself in danger"}),"\n",(0,h.jsx)(n,{verse:24,children:"And he took gold, and silver, and raiment, and many other presents, and went to the king to Ptolemais and he found favour in his sight."}),"\n",(0,h.jsx)(n,{verse:25,children:"And certain wicked men of his nation made complaints against him."}),"\n",(0,h.jsx)(n,{verse:26,children:"And the king treated him as his predecessors had done before: and he exalted him in the sight of all his friends."}),"\n",(0,h.jsx)(n,{verse:27,children:"And he confirmed him in the high priesthood and all the honours he had before, and he made him the chief of his friends."}),"\n",(0,h.jsx)(n,{verse:28,children:"And Jonathan requested of the king that he would make Judea free from tribute, and the three governments, and Samaria, and the confines thereof: and he promised him three hundred talents."}),"\n",(0,h.jsx)(n,{verse:29,children:"And the king consented: and he wrote letters to Jonathan of all these things, to this effect."}),"\n",(0,h.jsx)(n,{verse:30,children:"King Demetrius to his brother, Jonathan, and to the nation of the Jews, greeting."}),"\n",(0,h.jsx)(n,{verse:31,children:"We send you here a copy of the letter which we have written to Lasthenes, our parent, concerning you, that you might know it."}),"\n",(0,h.jsx)(n,{verse:32,children:"King Demetrius to Lasthenes, his parent, greetings."}),"\n",(0,h.jsx)(n,{verse:33,children:"We have determined to do good to the nation of the Jews, who are our friends, and keep the things that are just with us, for their good will which they bear towards us."}),"\n",(0,h.jsx)(n,{verse:34,children:"We have ratified, therefore, unto them all the borders of Judea, and the three cities, Apherema, Lydda, and Ramatha, which are added to Judea, out of Samaria, and all their confines, to be set apart to all them that sacrifice in Jerusalem, instead of the payments which the king received of them every year, and for the fruits of the land, and of the trees."}),"\n",(0,h.jsx)(t.admonition,{type:"note",children:(0,h.jsx)(t.p,{children:"Note 1: Apherema...is found only in the Greek version."})}),"\n",(0,h.jsx)(n,{verse:35,children:"And as for other things that belonged to us of the tithes, and of the tributes, from this time we discharge them of them: the saltpans also, and the crowns that were presented to us."}),"\n",(0,h.jsx)(n,{verse:36,children:"We give all to them, and nothing hereof shall be revoked from this time forth and for ever."}),"\n",(0,h.jsx)(n,{verse:37,children:"Now, therefore, see that thou make a copy of these things, and let it be given to Jonathan, and set upon the holy mountain, in a conspicuous place."}),"\n",(0,h.jsx)(n,{verse:38,children:"And king Demetrius, seeing that the land was quiet before him, and nothing resisted him, sent away all his forces, every man to his own place, except the foreign army, which he had drawn together from the islands of the nations: so all the troops of his fathers hated him."}),"\n",(0,h.jsx)(n,{verse:39,children:"Now there was one Tryphon who had been of Alexander's party before: who seeing that all the army murmured against Demetrius, went to Emalchuel, the Arabian, who brought up Antiochus, the son of Alexander:"}),"\n",(0,h.jsx)(n,{verse:40,children:"And he pressed him much to deliver him to him, that he might be king in his father's place: and he told him all that Demetrius had done, and how his soldiers hated him. And he remained there many days."}),"\n",(0,h.jsx)(n,{verse:41,children:"And Jonathan sent to king Demetrius, desiring that he would cast out them that were in the castle in Jerusalem, and those that were in the strong holds: because they fought against Israel."}),"\n",(0,h.jsx)(n,{verse:42,children:"And Demetrius sent to Jonathan, saying: I will not only do this for thee, and for thy people, but I will greatly honour thee, and thy nation, when opportunity shall serve."}),"\n",(0,h.jsx)(n,{verse:43,children:"Now, therefore, thou shalt do well if thou send me men to help me: for all my army is gone from me."}),"\n",(0,h.jsx)(n,{verse:44,children:"And Jonathan sent him three thousand valiant men to Antioch: and they came to the king, and the king was very glad of their coming."}),"\n",(0,h.jsx)(n,{verse:45,children:"And they that were of the city assembled themselves together, to the number of a hundred and twenty thousand men, and would have killed the king."}),"\n",(0,h.jsx)(n,{verse:46,children:"And the king fled into the palace: and they of the city kept the passages of the city, and began to fight."}),"\n",(0,h.jsx)(n,{verse:47,children:"And the king called the Jews to his assistance: and they came to him all at once, and they all dispersed themselves through the city."}),"\n",(0,h.jsx)(n,{verse:48,children:"And they slew in that day a hundred thousand men, and they set fire to the city, and got many spoils that day, and delivered the king."}),"\n",(0,h.jsx)(n,{verse:49,children:"And they that were of the city saw that the Jews had got the city as they would: and they were discouraged in their mind, and cried to the king, making supplication, and saying"}),"\n",(0,h.jsx)(n,{verse:50,children:"Grant us peace, and let the Jews cease from assaulting us, and the city."}),"\n",(0,h.jsx)(n,{verse:51,children:"And they threw down their arms, and made peace, and the Jews were glorified in the sight of the king, and in the sight of all that were in his realm, and were renowned throughout the kingdom, and returned to Jerusalem with many spoils."}),"\n",(0,h.jsx)(n,{verse:52,children:"So king Demetrius sat in the throne of his kingdom: and the land was quiet before him."}),"\n",(0,h.jsx)(n,{verse:53,children:"And he falsified all whatsoever he had said, and alienated himself from Jonathan, and did not reward him according to the benefits he had received from him, but gave him great trouble."}),"\n",(0,h.jsx)(n,{verse:54,children:"And after this Tryphon returned, and with him Antiochus, the young boy, who was made king, and put on the diadem."}),"\n",(0,h.jsx)(n,{verse:55,children:"And there assembled unto him all the hands which Demetrius had sent away, and they fought against Demetrius who turned his back and fled."}),"\n",(0,h.jsx)(n,{verse:56,children:"And Tryphon took the elephants, and made himself master of Antioch."}),"\n",(0,h.jsx)(n,{verse:57,children:"And young Antiochus wrote to Jonathan, saying: I confirm thee in the high priesthood, and I appoint thee ruler over the four cities, and to be one of the king's friends."}),"\n",(0,h.jsx)(n,{verse:58,children:"And he sent him vessels of gold for his service, and he gave him leave to drink in gold, and to be clothed in purple, and to wear a golden buckle:"}),"\n",(0,h.jsx)(n,{verse:59,children:"And he made his brother, Simon, governor, from the borders of Tyre even to the confines of Egypt."}),"\n",(0,h.jsx)(n,{verse:60,children:"Then Jonathan went forth, and passed through the cities beyond the river, and all the forces of Syria gathered themselves to him to help him, and he came to Ascalon, and they met him honourably out of the city."}),"\n",(0,h.jsx)(n,{verse:61,children:"And he went from thence to Gaza: and they that were in Gaza shut him out: and he besieged it, and burnt all the suburbs round about, and took the spoils."}),"\n",(0,h.jsx)(n,{verse:62,children:"And the men of Gaza made supplication to Jonathan, and he gave them the right hand: and he took their sons for hostages, and sent them to Jerusalem: and he went through the country, as far as Damascus."}),"\n",(0,h.jsx)(n,{verse:63,children:"And Jonathan heard that the generals of Demetrius were come treacherously to Cades, which is in Galilee, with a great army, purposing to remove him from the affairs of the kingdom."}),"\n",(0,h.jsx)(n,{verse:64,children:"And he went against them: but left his brother, Simon, in the country."}),"\n",(0,h.jsx)(n,{verse:65,children:"And Simon encamped against Bethsura, and assaulted it many days, and shut them up."}),"\n",(0,h.jsx)(n,{verse:66,children:"And they desired him to make peace, and he granted it them: and he cast them out from thence, and took the city, and placed a garrison in it."}),"\n",(0,h.jsx)(n,{verse:67,children:"And Jonathan and his army encamped by the water of Genesar, and before it was light they were ready in the plain of Asor."}),"\n",(0,h.jsx)(n,{verse:68,children:"And behold the army of the strangers met him in the plain, and they laid an ambush for him in the mountains: but he went out against them."}),"\n",(0,h.jsx)(n,{verse:69,children:"And they that lay in ambush rose out of their places, and joined battle."}),"\n",(0,h.jsx)(n,{verse:70,children:"And all that were on Jonathan's side fled, and none was left of them, but Mathathias, the son of Absalom, and Judas, the son of Calphi, chief captain of the army."}),"\n",(0,h.jsx)(n,{verse:71,children:"And Jonathan rent his garments, and cast earth upon his head, and prayed."}),"\n",(0,h.jsx)(n,{verse:72,children:"And Jonathan turned again to them to battle, and he put them to flight, and they fought."}),"\n",(0,h.jsx)(n,{verse:73,children:"And they of his part that fled saw this, and they turned again to him, and they all with him pursued the enemies, even to Cades, to their own camp, and they came even thither."}),"\n",(0,h.jsx)(n,{verse:74,children:"And there fell of the aliens in that day three thousand men: and Jonathan returned to Jerusalem."})]})}function c(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,h.jsx)(t,{...e,children:(0,h.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>i,x:()=>r});var h=n(14041);const a={},s=h.createContext(a);function i(e){const t=h.useContext(s);return h.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),h.createElement(s.Provider,{value:t},e.children)}}}]);